<?php

namespace Tests\Feature\Security;

use App\Services\JwtService;
use Illuminate\Support\Facades\Artisan;
use Tests\TestCase;

/**
 * Security scan 2026-09-15, item 4. The RS256 key pair was committed to git.
 * Keys are now per environment, generated by opescare:jwt-keys, read from
 * config, and never tracked.
 */
class JwtKeysAreNotCommittedTest extends TestCase
{
    public function test_no_private_key_is_tracked_by_git(): void
    {
        $tracked = shell_exec('git -C ' . escapeshellarg(base_path()) . ' ls-files -- "*.pem" "*.key" 2>&1');
        $this->assertSame('', trim((string) $tracked), "Key files are tracked by git:\n" . $tracked);
    }

    public function test_the_command_generates_a_pair_the_service_signs_and_verifies_with(): void
    {
        $dir = storage_path('framework/testing/jwt-' . uniqid());
        config([
            'jwt.private_key_path' => $dir . '/private.pem',
            'jwt.public_key_path'  => $dir . '/public.pem',
        ]);

        $this->assertSame(0, Artisan::call('opescare:jwt-keys'));
        $this->assertFileExists($dir . '/private.pem');
        $this->assertFileExists($dir . '/public.pem');

        // Refuses to overwrite without --force (replacing keys invalidates tokens).
        $this->assertSame(1, Artisan::call('opescare:jwt-keys'));

        $service = app(JwtService::class);
        $ref = new \ReflectionClass($service);
        foreach (['privateKey', 'publicKey'] as $method) {
            $m = $ref->getMethod($method);
            $m->setAccessible(true);
            $this->assertInstanceOf(\OpenSSLAsymmetricKey::class, $m->invoke($service), "$method reads the configured path");
        }

        array_map('unlink', glob($dir . '/*.pem'));
        @rmdir($dir);
    }
}
